const _meterInterval = setInterval(() => {
  _level = Math.max(0, _level - 0.04);
  if (_level > _peakHold) {
    _peakHold = _level;
    clearTimeout(_peakTimer);
    _peakTimer = setTimeout(() => { _peakHold = 0; }, 1800);
  }
  sBus.publish('org:meter', { level: _level, peak: _peakHold });
}, 33);
